input.command:
cat > package.json <<'EOF'
{
  "name": "qrypt-aes-key",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Generate an AES-256 key from Qrypt quantum entropy",
  "engines": { "node": ">=20.12" },
  "scripts": {
    "start": "node generate-key.mjs"
  }
}
EOF
cat > .gitignore <<'EOF'
.env
*.key
node_modules/
EOF
cat > generate-key.mjs <<'EOF'
// Generate an AES-256 key from Qrypt quantum entropy.
// Usage: node generate-key.mjs [output-path]   (default: aes256.key)
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";

const BASE_URL = "https://api-eus.qrypt.com";
const KEY_BYTES = 32;
const outPath = process.argv[2] ?? "aes256.key";

try {
  process.loadEnvFile(".env");
} catch (err) {
  if (err.code !== "ENOENT") throw err;
}
const token = process.env.QRYPT_API_KEY?.trim();
if (!token) {
  console.error("QRYPT_API_KEY is not set (expected in .env or the environment).");
  process.exit(1);
}

async function fetchEntropy(kib = 1) {
  const res = await fetch(`${BASE_URL}/api/v1/quantum-entropy?size=${kib}`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: "application/json",
      "User-Agent": "qrypt-aes-key/1.0",
      "X-Qrypt-Client": "qrypt-aes-key",
    },
  });
  if (!res.ok) {
    const hints = {
      400: "invalid size parameter",
      401: "missing, malformed, or expired Authorization header",
      403: "invalid token or monthly quota exhausted",
      429: "rate limited; wait at least 10 seconds before retrying",
    };
    throw new Error(`Qrypt API ${res.status}: ${hints[res.status] ?? "service error, try again later"}`);
  }
  const body = await res.json();
  if (!Array.isArray(body.random) || body.random.length === 0) {
    throw new Error("Unexpected response: missing 'random' array");
  }
  return Buffer.concat(body.random.map((b64) => Buffer.from(b64, "base64")));
}

const entropy = await fetchEntropy(1);
if (entropy.length < KEY_BYTES) {
  throw new Error(`Received only ${entropy.length} bytes of entropy`);
}
const key = Buffer.from(entropy.subarray(0, KEY_BYTES));
entropy.fill(0);

// Sanity check: AES-256-GCM round trip.
const nonce = randomBytes(12);
const plaintext = Buffer.from("Hello from quantum entropy!");
const cipher = createCipheriv("aes-256-gcm", key, nonce);
const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
const tag = cipher.getAuthTag();
const decipher = createDecipheriv("aes-256-gcm", key, nonce);
decipher.setAuthTag(tag);
const roundTrip = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
if (!roundTrip.equals(plaintext)) throw new Error("AES-256-GCM round trip failed");

writeFileSync(outPath, key.toString("hex") + "\n", { mode: 0o600 });
const fingerprint = createHash("sha256").update(key).digest("hex").slice(0, 16);
key.fill(0);

console.log(`AES-256 key written to ${outPath} (mode 600)`);
console.log(`Key fingerprint (SHA-256, first 8 bytes): ${fingerprint}`);
console.log("AES-256-GCM encrypt/decrypt round trip: OK");
EOF
node --check generate-key.mjs && echo syntax ok
ls -la

